p=argparse.ArgumentParser();p.add_argument('--feature',choices=['rally','civ'],required=True);p.add_argument('--url',required=True);p.add_argument('--expected',required=True);p.add_argument('--out',type=Path,required=True);a=p.parse_args();assert a.url.startswith('http://127.0.0.1:');a.out.mkdir(exist_ok=True,parents=True);r={'feature':a.feature,'stage':'AFTER_LOCAL','actions':[],'checks':[],'console':[],'page_errors':[],'failed':[],'pass':False}
