 b=pw.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox']);c=b.new_context(viewport={'width':1600,'height':1100},record_har_path=str(a.out/'network.har'));c.tracing.start(screenshots=False,snapshots=True);page=c.new_page();page.on('console',lambda m:r['console'].append({'type':m.type,'text':m.text}));page.on('pageerror',lambda e:r['page_errors'].append(str(e)));page.on('requestfailed',lambda q:r['failed'].append({'url':q.url,'error':q.failure}))
